"""Founder import. Gitignored name map. Never commit relations.yaml."""

from __future__ import annotations

import json
from pathlib import Path

from hades_runtime.store import Store


def load_name_map(path) -> dict:
    p = Path(path)
    if not p.name.endswith(".local.json"):
        raise ValueError("name map must be gitignored *.local.json")
    return json.loads(p.read_text(encoding="utf-8"))


def import_founder(
    store: Store,
    account_id: str,
    snapshot: dict,
    name_map: dict,
    timezone: str | None = None,
) -> dict:
    if not account_id:
        raise ValueError("no account_id")
    if not name_map:
        raise ValueError("name map required")
    tz = timezone or snapshot.get("timezone") or "UTC"
    store.create_account(account_id, timezone=tz)
    cs = snapshot.get("character_state") or {}
    store.tick_account(account_id, cs)
    if snapshot.get("opted_in_inner_life"):
        store.set_opted_in_inner_life(account_id, True)
    for person in snapshot.get("people") or []:
        raw = person.get("name")
        if raw not in name_map:
            raise ValueError("unmapped person")
        ident = name_map[raw]
        store.write(
            account_id,
            ident["person_id"],
            {
                "center": person.get("center") or 0.0,
                "depth": person.get("depth") or 0.0,
                "secrets": list(person.get("secrets") or []),
                "episodic": list(person.get("episodic") or []),
                "flags": {
                    "is_partner": bool(ident.get("is_partner")),
                    "is_family": bool(ident.get("is_family")),
                },
            },
        )
    return store.get_account(account_id)

