from __future__ import annotations

import copy

from hades_runtime.physics import apply_elapsed, inner_life_jobs, parse_time
from hades_runtime.state import (
    account_id_from_auth,
    clamp_character_patch,
    zero_account,
)

RECENT_CAP = 15


class Store:
    def __init__(self) -> None:
        self._data: dict[tuple[str, str], dict] = {}
        self._accounts: dict[str, dict] = {}

    def write(self, account_id: str, person_id: str, payload: dict) -> None:
        if account_id and account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
            self._persist_account(account_id)
        key = (account_id, person_id)
        row = dict(self._data.get(key) or {})
        row.update(payload)
        self._data[key] = row

    def read(self, account_id: str, person_id: str, field: str | None = None):
        row = self._data.get((account_id, person_id)) or {}
        if field is None:
            return dict(row)
        return row.get(field)

    def list_people(self, account_id: str) -> list[str]:
        return sorted(person_id for acc, person_id in self._data if acc == account_id)

    def create_account(self, account_id: str, timezone: str = "UTC") -> dict:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id, timezone)
            self._persist_account(account_id)
        return self.get_account(account_id)

    def get_account(self, account_id: str) -> dict | None:
        row = self._accounts.get(account_id)
        if row is None:
            return None
        return copy.deepcopy(row)

    def get_account_for_request(
        self, token_account_id: str, body_account_id: str | None = None
    ) -> dict:
        account_id = account_id_from_auth(token_account_id, body_account_id)
        existing = self.get_account(account_id)
        if existing is not None:
            return existing
        return self.create_account(account_id)

    def set_opted_in_inner_life(self, account_id: str, opted_in: bool) -> None:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
        self._accounts[account_id]["opted_in_inner_life"] = bool(opted_in)
        self._persist_account(account_id)

    def set_timestamps(self, account_id: str, *, last_tick=None, last_inbound=None) -> None:
        if not account_id:
            raise ValueError("no account_id")
        if account_id not in self._accounts:
            self._accounts[account_id] = zero_account(account_id)
        if last_tick is not None:
            stamp = parse_time(last_tick)
            self._accounts[account_id]["last_tick"] = stamp.isoformat() if stamp else None
        if last_inbound is not None:
            stamp = parse_time(last_inbound)

