class FileStore(Store):
    def __init__(self, root) -> None:
        super().__init__()
        from pathlib import Path
        import json

        self._root = Path(root)
        self._root.mkdir(parents=True, exist_ok=True)
        self._json = json
        self._load()

    def _path(self, account_id: str, person_id: str):
        safe = f"{account_id}__{person_id}.json".replace("/", "_")
        return self._root / safe

    def _account_path(self, account_id: str):
        safe = f"{account_id}.account.json".replace("/", "_")
        return self._root / safe

    def _load(self) -> None:
        for path in self._root.glob("*.account.json"):
            row = self._json.loads(path.read_text(encoding="utf-8"))
            self._accounts[row["account_id"]] = row
        for path in self._root.glob("*.json"):
            if path.name.endswith(".account.json"):
                continue
            row = self._json.loads(path.read_text(encoding="utf-8"))
            acc, person = row["account_id"], row["person_id"]
            data = dict(row)
            data.pop("account_id", None)
            data.pop("person_id", None)
            self._data[(acc, person)] = data

    def write(self, account_id: str, person_id: str, payload: dict) -> None:
        super().write(account_id, person_id, payload)
        row = {
            "account_id": account_id,
            "person_id": person_id,
            **self._data[(account_id, person_id)],
        }
        self._path(account_id, person_id).write_text(
            self._json.dumps(row), encoding="utf-8"
        )

    def _persist_account(self, account_id: str) -> None:
        row = self._accounts[account_id]
        self._account_path(account_id).write_text(
