)


def clamp_mood(value: float) -> float:
    return max(MOOD_MIN, min(MOOD_MAX, float(value)))


def clamp_fatigue(value: float) -> float:
    return max(FATIGUE_MIN, min(FATIGUE_MAX, float(value)))


def clamp_depth(value: float) -> float:
    return max(DEPTH_MIN, min(DEPTH_MAX, float(value)))


